class MailyInstruction34StateEvaluator(BaseEvaluator):
    """Validate all eleven durable outcomes without changing simulator state."""

    DEFAULT_API_BASE_URL = "http://127.0.0.1:8081"
    DEFAULT_TIMEOUT_SECONDS = 5.0
    DEFAULT_POLL_INTERVAL_SECONDS = 0.5
    DEFAULT_LLDB_TIMEOUT_SECONDS = 20.0

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        api_base_url = str(params.get("api_base_url") or self.DEFAULT_API_BASE_URL).rstrip("/")
        udid = str(params.get("udid") or "").strip()
        bundle_id = str(params.get("bundle_id") or "de.enough.maily").strip()
        expected_email = str(params.get("expected_account_email") or SENDER_EMAIL).strip().lower()
        expected_name = str(params.get("expected_account_name") or "Incident Desk")
        expected_ruleset = str(params.get("expected_ruleset_sha256") or "").strip()
        timeout_seconds = float(params.get("timeout_seconds", self.DEFAULT_TIMEOUT_SECONDS) or 0.0)
        poll_interval_seconds = float(
            params.get("poll_interval_seconds", self.DEFAULT_POLL_INTERVAL_SECONDS) or 0.0
        )
        lldb_timeout_seconds = float(
            params.get("lldb_timeout_seconds", self.DEFAULT_LLDB_TIMEOUT_SECONDS) or 0.0
        )

        if expected_ruleset and expected_ruleset != RULESET_SHA256:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="Configured evaluator ruleset digest does not match implementation",
                metadata={
                    **self._base_metadata(api_base_url),
                    "expected_ruleset_sha256": expected_ruleset,
                    "observed_ruleset_sha256": RULESET_SHA256,
                    "runtime_healthy": False,
                },
            )
        if not udid:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="A runner-bound iOS simulator UDID is required",
                metadata={**self._base_metadata(api_base_url), "runtime_healthy": False},
            )

        try:
            simulator = self._read_simulator_evidence(udid)
            if simulator["state"] != "Booted":
                raise RuntimeError(
                    f"bound simulator must already be Booted, observed {simulator['state'] or 'unknown'}"
                )
            account = self._read_account_evidence(
                udid=udid,
                bundle_id=bundle_id,
                expected_email=expected_email,
                timeout_seconds=lldb_timeout_seconds,
            )
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"Read-only Maily account query failed: {type(exc).__name__}: {exc}",
                metadata={
                    **self._base_metadata(api_base_url),
                    "runtime_healthy": False,
                    "runtime_error_type": type(exc).__name__,
                },
            )

        deadline = time.monotonic() + max(timeout_seconds, 0.0)
        while True:
            try:
                mailboxes = {
                    mailbox: self._fetch_mailbox_messages(
                        api_base_url=api_base_url,
                        recipient_email=mailbox,
                    )
                    for mailbox in sorted({str(spec["mailbox"]) for spec in CHECKPOINT_SPECS})
                }
                result = self._evaluate_state(
                    mailboxes,
                    account_evidence=account,
                    session_start=simulator["last_booted_at"],
                    expected_account_email=expected_email,
                    expected_account_name=expected_name,
                    api_base_url=api_base_url,
                    simulator_evidence=simulator,
                )
            except Exception as exc:
                return EvalResult(
                    status=EvalStatus.ERROR,
                    message=f"Read-only lightweight-mail query failed: {type(exc).__name__}: {exc}",
                    metadata={
                        **self._base_metadata(api_base_url),
                        "runtime_healthy": True,
                        "runtime_error_type": type(exc).__name__,
                    },
                )
            if result.status is EvalStatus.PASS or time.monotonic() >= deadline:
                return result
            if poll_interval_seconds <= 0:
                return result
            time.sleep(min(poll_interval_seconds, max(0.0, deadline - time.monotonic())))

    @classmethod
    def _evaluate_state(
        cls,
        mailboxes: Mapping[str, list[dict[str, Any]]],
        *,
        account_evidence: Mapping[str, Any],
        session_start: datetime,
        expected_account_email: str = SENDER_EMAIL,
        expected_account_name: str = "Incident Desk",
        api_base_url: str = "test://lightweight-mail",
        simulator_evidence: Mapping[str, Any] | None = None,
    ) -> EvalResult:
        message_checks: list[dict[str, Any]] = []
        matches: list[dict[str, Any] | None] = []
        for spec in CHECKPOINT_SPECS:
            check, match = cls._evaluate_checkpoint(
                spec,
                mailboxes.get(str(spec["mailbox"]), []),
                session_start=session_start,
            )
            message_checks.append(check)
            matches.append(match)

        order_check = cls._global_order_check(matches)
        uid_check = cls._mailbox_uid_order_check(matches)
        first_delivery = (
            matches[0]["parsed"]["parsed_date"] if matches and matches[0] is not None else None
        )
        account_check = cls._account_check(
            account_evidence,
            expected_email=expected_account_email,
            expected_name=expected_account_name,
            session_start=session_start,
            first_delivery=first_delivery,
        )
        checks = [account_check, *message_checks, order_check, uid_check]
        failures = [check for check in checks if not check["pass"]]

        coverage_details = cls._coverage_details()
        if not coverage_details["all_steps_covered_exactly_once"]:
            coverage_failure = {
                "name": "complete_76_step_coverage",
                "pass": False,
                "failure_reason": "The static checkpoint map does not cover steps 1-76 exactly once.",
                "observed": coverage_details,
            }
            checks.append(coverage_failure)
            failures.append(coverage_failure)

        checkpoint_checks = [account_check, *message_checks]
        step_coverage = cls._step_coverage_records(
            checkpoint_checks,
            mail_order_passed=order_check["pass"] and uid_check["pass"],
        )
        metadata = cls._base_metadata(api_base_url)
        metadata.update(
            {
                "runtime_healthy": True,
                "checks": checks,
                "failures": failures,
                "step_coverage": step_coverage,
                "step_coverage_details": coverage_details,
                "coverage_summary": {
                    "instruction_step_count": 76,
                    "checkpoint_count": len(STEP_GROUPS),
                    "covered_step_count": len(coverage_details["covered_steps"]),
                    "all_steps_covered_exactly_once": coverage_details[
                        "all_steps_covered_exactly_once"
                    ],
                },
                "order_evidence": {
                    "account_modified_before_first_delivery": account_check["observed"],
                    "global_delivery_order": order_check["observed"],
                    "same_mailbox_uid_order": uid_check["observed"],
                },
                "observed": {
                    "simulator": {
                        key: value.isoformat() if isinstance(value, datetime) else value
                        for key, value in dict(simulator_evidence or {}).items()
                    },
                    "account": dict(account_evidence),
                    "mailbox_message_counts": {
                        mailbox: len(messages) for mailbox, messages in mailboxes.items()
                    },
                    "matched_messages": [
                        match["evidence"] if match is not None else None for match in matches
                    ],
                },
            }
        )
        if failures:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Maily instruction 3-4 durable state failed one or more strict checks",
                metadata=metadata,
            )
        return EvalResult(
            status=EvalStatus.PASS,
            message="Maily instruction 3-4 durable state matches all strict read-only checks",
            metadata=metadata,
        )

