    @classmethod
    def _evaluate_checkpoint(
        cls,
        spec: Mapping[str, Any],
        rows: list[dict[str, Any]],
        *,
        session_start: datetime,
    ) -> tuple[dict[str, Any], dict[str, Any] | None]:
        subject_rows: list[dict[str, Any]] = []
        valid_matches: list[dict[str, Any]] = []
        candidate_observations: list[dict[str, Any]] = []
        for row in rows:
            parsed = cls._parse_row(row)
            if parsed["subject"] != spec["subject"]:
                continue
            subject_rows.append(row)
            issues, evidence = cls._validate_candidate(
                spec,
                parsed,
                session_start=session_start,
            )
            candidate_observations.append({"issues": issues, "evidence": evidence})
            if not issues:
                valid_matches.append({"parsed": parsed, "evidence": evidence})

        passed = len(valid_matches) == 1
        check: dict[str, Any] = {
            "name": str(spec["name"]),
            "pass": passed,
            "steps": list(spec["steps"]),
            "expected": {key: value for key, value in spec.items() if key not in {"name", "steps"}},
            "observed": {
                "target_subject_candidate_count": len(subject_rows),
                "fully_valid_match_count": len(valid_matches),
                "candidates": candidate_observations,
            },
        }
        if not passed:
            check["failure_reason"] = (
                "No message satisfies every exact field, current-session, provenance, and attachment requirement."
                if not valid_matches
                else f"Expected one unique valid message, found {len(valid_matches)}."
            )
        return check, valid_matches[0] if passed else None

    @classmethod
    def _validate_candidate(
        cls,
        spec: Mapping[str, Any],
        parsed: Mapping[str, Any],
        *,
        session_start: datetime,
    ) -> tuple[list[str], dict[str, Any]]:
        issues: list[str] = []
        mailbox = str(spec["mailbox"]).lower()
        if parsed["from"] != [SENDER_EMAIL]:
            issues.append(f"from must equal [{SENDER_EMAIL!r}]")
        if parsed["to"] != [mailbox]:
            issues.append(f"to must equal [{mailbox!r}]")
        if parsed["subject"] != spec["subject"]:
            issues.append("subject mismatch")
        if parsed["authored_text"] != spec["authored_text"]:
            issues.append("user-authored plain-text body mismatch")

        kind = str(spec["kind"])
        relation_sources: list[str] = []
        relation_haystacks = {
            "In-Reply-To": cls._compact_header(str(parsed["in_reply_to"])),
            "References": cls._compact_header(str(parsed["references"])),
            "quoted_original": cls._compact_header(str(parsed["quoted_text"])),
        }
        if kind == "compose":
            if parsed["in_reply_to"] or parsed["references"]:
                issues.append("ordinary composed message must not contain thread relation headers")
            if cls._looks_like_quoted_original(str(parsed["plain_text"])):
                issues.append("ordinary composed message must not masquerade as reply/forward")
        else:
            fragment = cls._compact_header(str(spec["source_message_id_fragment"]))
            source_subject = cls._compact_header(str(spec["source_subject"]))
            for source_name, haystack in relation_haystacks.items():
                if fragment in haystack or (
                    source_name == "quoted_original" and source_subject in haystack
                ):
                    relation_sources.append(source_name)
            if not relation_sources:
                issues.append("reply/forward is not bound to the required seed message")

        expected_attachments = list(spec["attachments"])
        observed_attachments = list(parsed["attachments"])
        if len(observed_attachments) != len(expected_attachments):
            issues.append(
                f"attachment count must be {len(expected_attachments)}, got {len(observed_attachments)}"
            )
        else:
            for expected, observed in zip(expected_attachments, observed_attachments):
                if expected.get("filename") is not None and observed["filename"] != expected["filename"]:
                    issues.append("attachment filename mismatch")
                if observed["content_type"] != expected["content_type"]:
                    issues.append("attachment content type mismatch")
                if observed["sha256"] != expected["sha256"]:
                    issues.append("attachment SHA-256 mismatch")

        parsed_date = parsed["parsed_date"]
        if parsed_date is None:
            issues.append("Date header is missing or unparseable")
        elif parsed_date <= session_start:
            issues.append("message was not delivered during the current simulator boot session")
        if parsed["uid"] is None:
            issues.append("mailbox UID is missing or non-numeric")

        evidence = {
            "mailbox": spec["mailbox"],
            "uid": parsed["uid"],
            "date": parsed["date"],
            "parsed_date": parsed_date.isoformat() if parsed_date is not None else None,
            "from": parsed["from"],
            "to": parsed["to"],
            "subject": parsed["subject"],
            "authored_text": parsed["authored_text"],
            "relation_sources": relation_sources,
            "attachments": observed_attachments,
        }
        return issues, evidence

    @staticmethod
    def _account_check(
        evidence: Mapping[str, Any],
        *,
        expected_email: str,
        expected_name: str,
        session_start: datetime,
        first_delivery: datetime | None,
    ) -> dict[str, Any]:
        modified_at = MailyInstruction34StateEvaluator._parse_iso_datetime(
            str(evidence.get("modified_at") or "")
        )
        issues: list[str] = []
        if int(evidence.get("query_status", -1)) != 0:
            issues.append("SecItemCopyMatching did not return errSecSuccess")
        if int(evidence.get("matching_account_count", 0)) != 1:
            issues.append("expected exactly one secure-storage account matching the target email")
        if str(evidence.get("account_email") or "").lower() != expected_email.lower():
            issues.append("secure-storage account email mismatch")
        if str(evidence.get("account_name") or "") != expected_name:
            issues.append("secure-storage account name mismatch")
        if modified_at is None:
            issues.append("secure-storage modification date is missing or unparseable")
        elif modified_at <= session_start:
            issues.append("account was not modified during the current simulator boot session")
        if first_delivery is None:
            issues.append("first required delivery is missing, so rename-before-send cannot be proven")
        elif modified_at is not None and modified_at >= first_delivery:
            issues.append("account modification does not precede the first required delivery")

        check: dict[str, Any] = {
            "name": "account_name_incident_desk",
            "pass": not issues,
            "steps": list(range(1, 6)),
            "expected": {
                "account_email": expected_email,
                "account_name": expected_name,
                "modified_after": session_start.isoformat(),
                "modified_before_first_delivery": True,
            },
            "observed": {
                "query_status": evidence.get("query_status"),
                "matching_account_count": evidence.get("matching_account_count"),
                "account_email": evidence.get("account_email"),
                "account_name": evidence.get("account_name"),
                "modified_at": modified_at.isoformat() if modified_at else None,
                "first_delivery": first_delivery.isoformat() if first_delivery else None,
                "lldb_detached": evidence.get("lldb_detached"),
            },
        }
        if issues:
            check["failure_reason"] = "; ".join(issues)
        return check

    @classmethod
    def _parse_row(cls, row: Mapping[str, Any]) -> dict[str, Any]:
        raw = row.get("mimeMessage")
        if not isinstance(raw, str):
            raw = ""
        message = BytesParser(policy=policy.default).parsebytes(raw.encode("utf-8"))
        plain_text = cls._plain_text(message)
        authored_text, quoted_text = cls._split_authored_text(plain_text)
        date_value = str(message.get("Date") or "")
        try:
            uid = int(row.get("uid"))
        except (TypeError, ValueError):
            uid = None
        return {
            "uid": uid,
            "date": date_value,
            "parsed_date": cls._parse_mail_date(date_value),
            "from": cls._addresses(message, "From"),
            "to": cls._addresses(message, "To"),
            "subject": str(message.get("Subject") or row.get("subject") or ""),
            "plain_text": plain_text,
            "authored_text": authored_text,
            "quoted_text": quoted_text,
            "in_reply_to": str(message.get("In-Reply-To") or ""),
            "references": str(message.get("References") or ""),
            "attachments": cls._attachments(message),
        }

    @staticmethod
    def _addresses(message: Message, header: str) -> list[str]:
        return [
            address.lower()
            for _name, address in getaddresses(message.get_all(header, []))
            if address
        ]

    @staticmethod
    def _plain_text(message: Message) -> str:
        parts = message.walk() if message.is_multipart() else (message,)
        for part in parts:
            if part.get_content_type() != "text/plain":
                continue
            if part.get_content_disposition() == "attachment":
                continue
            try:
                content = part.get_content()
            except (LookupError, UnicodeError):
                payload = part.get_payload(decode=True) or b""
                content = payload.decode(part.get_content_charset() or "utf-8", errors="replace")
            return str(content).replace("\r\n", "\n").replace("\r", "\n")
        return ""

    @staticmethod
    def _split_authored_text(plain_text: str) -> tuple[str, str]:
        marker_patterns = (
            r">\s*On\s+.+?wrote:",
            r">?\s*-{5,}\s*Original Message\s*-{5,}",
        )
        starts = [
            match.start()
            for pattern in marker_patterns
            if (match := re.search(pattern, plain_text, flags=re.IGNORECASE | re.DOTALL))
        ]
        if not starts:
            return plain_text.strip(), ""
        index = min(starts)
        return plain_text[:index].strip(), plain_text[index:].strip()

    @staticmethod
    def _looks_like_quoted_original(text: str) -> bool:
        return "original message" in text.lower() or bool(
            re.search(r">\s*on\s+.+?wrote:", text, re.I | re.S)
        )

    @staticmethod
    def _compact_header(value: str) -> str:
        return re.sub(r"\s+", "", value).lower()

    @staticmethod
    def _parse_mail_date(value: str) -> datetime | None:
        try:
            parsed = parsedate_to_datetime(value)
        except (TypeError, ValueError, OverflowError):
            return None
        if parsed is None:
            return None
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)

    @staticmethod
    def _parse_iso_datetime(value: str) -> datetime | None:
        if not value:
            return None
        try:
            parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        except ValueError:
            return None
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)

    @staticmethod
    def _attachments(message: Message) -> list[dict[str, Any]]:
        attachments: list[dict[str, Any]] = []
        for part in message.walk():
            if part.is_multipart():
                continue
            filename = part.get_filename()
            if part.get_content_disposition() != "attachment" and filename is None:
                continue
            payload = part.get_payload(decode=True) or b""
            attachments.append(
                {
                    "filename": filename,
                    "content_type": part.get_content_type().lower(),
                    "size": len(payload),
                    "sha256": hashlib.sha256(payload).hexdigest(),
                }
            )
        return attachments

    @staticmethod
    def _global_order_check(matches: list[dict[str, Any] | None]) -> dict[str, Any]:
        evidence = [match["evidence"] if match is not None else None for match in matches]
        parsed_dates = [
            match["parsed"]["parsed_date"] if match is not None else None for match in matches
        ]
        passed = all(value is not None for value in parsed_dates) and all(
            parsed_dates[index] < parsed_dates[index + 1]
            for index in range(len(parsed_dates) - 1)
        )
        check: dict[str, Any] = {
            "name": "global_delivery_date_order",
            "pass": passed,
            "steps": [int(spec["durable_step"]) for spec in CHECKPOINT_SPECS],
            "observed": evidence,
        }
        if not passed:
            check["failure_reason"] = (
                "Matched message Date values are not all present and strictly increasing."
            )
        return check

    @staticmethod
    def _mailbox_uid_order_check(matches: list[dict[str, Any] | None]) -> dict[str, Any]:
        by_mailbox: dict[str, list[dict[str, Any]]] = {}
        complete = all(match is not None for match in matches)
        for match in matches:
            if match is None:
                continue
            evidence = match["evidence"]
            by_mailbox.setdefault(str(evidence["mailbox"]), []).append(
                {"uid": evidence["uid"], "subject": evidence["subject"]}
            )
        passed = complete and all(
            all(
                rows[index]["uid"] is not None
                and rows[index + 1]["uid"] is not None
                and rows[index]["uid"] < rows[index + 1]["uid"]
                for index in range(len(rows) - 1)
            )
            for rows in by_mailbox.values()
        )
        check: dict[str, Any] = {
            "name": "same_mailbox_uid_order",
            "pass": passed,
            "steps": [int(spec["durable_step"]) for spec in CHECKPOINT_SPECS],
            "observed": by_mailbox,
        }
        if not passed:
            check["failure_reason"] = (
                "Matched UIDs are not all present and strictly increasing within each mailbox."
            )
        return check

    @staticmethod
    def _coverage_details() -> dict[str, Any]:
        covered = [int(step) for group in STEP_GROUPS for step in group["steps"]]
        counts: dict[int, int] = {}
        for step in covered:
            counts[step] = counts.get(step, 0) + 1
        duplicates = sorted(step for step, count in counts.items() if count != 1)
        unique = sorted(set(covered))
        return {
            "expected_steps": list(range(1, 77)),
            "covered_steps": unique,
            "missing_steps": sorted(set(range(1, 77)) - set(unique)),
            "duplicate_steps": duplicates,
            "all_steps_covered_exactly_once": unique == list(range(1, 77)) and not duplicates,
            "groups": [dict(group) for group in STEP_GROUPS],
        }

    @staticmethod
    def _step_coverage_records(
        checkpoint_checks: list[dict[str, Any]],
        *,
        mail_order_passed: bool,
    ) -> list[dict[str, Any]]:
        checks_by_name = {str(check["name"]): check for check in checkpoint_checks}
        records: list[dict[str, Any]] = []
        for group in STEP_GROUPS:
            checkpoint_name = str(group["checkpoint"])
            checkpoint_passed = checks_by_name.get(checkpoint_name, {}).get("pass") is True
            if checkpoint_name != "account_name_incident_desk":
                checkpoint_passed = checkpoint_passed and mail_order_passed
            dimensions = (
                {
                    "final_object": "Maily secure-storage account record",
                    "content": "exact account email and account name",
                    "source_or_process": "current-boot keychain modification before first delivery",
                    "final_ui": "not required and not claimed",
                }
                if checkpoint_name == "account_name_incident_desk"
                else {
                    "final_object": "unique delivered MIME message",
                    "content": "exact sender, recipient, subject, authored text, and attachment rules",
                    "source_or_process": "seed provenance plus current-session strict Date/UID sequence",
                    "final_ui": "not required and not claimed",
                }
            )
            for raw_step in group["steps"]:
                records.append(
                    {
                        "step": int(raw_step),
                        "pass": checkpoint_passed,
                        "checkpoint_names": [checkpoint_name],
                        "dimensions": dimensions,
                        "mapping_basis": (
                            "This step belongs to a compound durable chain whose final stored result "
                            "covers its navigation, field entry, source selection, attachment selection, "
                            "and submission actions."
                        ),
                    }
                )
        return sorted(records, key=lambda record: record["step"])

    @staticmethod
    def _read_simulator_evidence(udid: str) -> dict[str, Any]:
        proc = subprocess.run(
            ["xcrun", "simctl", "list", "devices", "--json"],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if proc.returncode != 0:
            raise RuntimeError(f"simctl list failed: {proc.stderr.strip()}")
        payload = json.loads(proc.stdout)
        for rows in payload.get("devices", {}).values():
            if not isinstance(rows, list):
                continue
            for row in rows:
                if isinstance(row, dict) and str(row.get("udid") or "") == udid:
                    last_booted_at = MailyInstruction34StateEvaluator._parse_iso_datetime(
                        str(row.get("lastBootedAt") or "") or DEFAULT_WINDOW_START
                    )
                    if last_booted_at is None:
                        raise RuntimeError("bound simulator has no usable window start")
                    return {
                        "udid": udid,
                        "name": str(row.get("name") or ""),
                        "state": str(row.get("state") or ""),
                        "last_booted_at": last_booted_at,
                        "last_booted_at_iso": last_booted_at.isoformat(),
                    }
        raise RuntimeError(f"bound simulator UDID was not found: {udid}")

    @classmethod
    def _read_account_evidence(
        cls,
        *,
        udid: str,
        bundle_id: str,
        expected_email: str,
        timeout_seconds: float,
    ) -> dict[str, Any]:
        app_path_proc = subprocess.run(
            ["xcrun", "simctl", "get_app_container", udid, bundle_id, "app"],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if app_path_proc.returncode != 0:
            raise RuntimeError(
                f"unable to resolve installed Maily app container: {app_path_proc.stderr.strip()}"
            )
        app_path = Path(app_path_proc.stdout.strip())
        with (app_path / "Info.plist").open("rb") as handle:
            info = plistlib.load(handle)
        executable_name = str(info.get("CFBundleExecutable") or "").strip()
        if not executable_name:
            raise RuntimeError("Maily Info.plist has no CFBundleExecutable")
        executable = str(app_path / executable_name)
        ps_proc = subprocess.run(
            ["ps", "-axo", "pid=,command="],
            capture_output=True,
            text=True,
            timeout=10,
        )
        if ps_proc.returncode != 0:
            raise RuntimeError(f"unable to inspect running Maily process: {ps_proc.stderr.strip()}")
        pids: list[int] = []
        for line in ps_proc.stdout.splitlines():
            match = re.match(r"\s*(\d+)\s+(.*)$", line)
            if match and match.group(2).strip() == executable:
                pids.append(int(match.group(1)))
        if len(pids) != 1:
            raise RuntimeError(
                f"expected one already-running Maily process for bound simulator, found {len(pids)}"
            )

        expression = cls._keychain_expression(expected_email)
        output, detached = cls._run_lldb_read(
            app_pid=pids[0],
            expression=expression,
            timeout_seconds=max(timeout_seconds, 1.0),
        )
        evidence_payload: dict[str, Any] | None = None
        for line in output.splitlines():
            candidate = line.strip()
            if not candidate.startswith("{") or not candidate.endswith("}"):
                continue
            try:
                parsed = json.loads(candidate)
            except json.JSONDecodeError:
                continue
            if isinstance(parsed, dict) and parsed.get("marker") == "MailyAccountEvidenceV1":
                evidence_payload = parsed
                break
        if evidence_payload is None:
            raise RuntimeError("LLDB keychain query returned no sanitized account evidence")
        return {
            "query_status": evidence_payload.get("query_status"),
            "matching_account_count": evidence_payload.get("matching_account_count"),
            "account_email": evidence_payload.get("account_email"),
            "account_name": evidence_payload.get("account_name"),
            "modified_at": evidence_payload.get("modified_at"),
            "storage_key": ACCOUNT_STORAGE_KEY,
            "transport": "SecItemCopyMatching via attached running Maily process",
            "app_process_pid": pids[0],
            "app_executable": executable_name,
            "lldb_detached": detached,
            "raw_keychain_payload_exposed": False,
        }

    @staticmethod
    def _keychain_expression(expected_email: str) -> str:
        escaped_email = expected_email.replace("\\", "\\\\").replace('"', '\\"')
        return (
            '(NSString *)({ NSDictionary *q = @{(id)kSecClass:(id)kSecClassGenericPassword,'
            f'(id)kSecAttrAccount:@"{ACCOUNT_STORAGE_KEY}",(id)kSecReturnAttributes:@YES,'
            '(id)kSecReturnData:@YES,(id)kSecMatchLimit:(id)kSecMatchLimitOne}; '
            'CFTypeRef ref = NULL; OSStatus st = SecItemCopyMatching((CFDictionaryRef)q, &ref); '
            'NSDictionary *item = (st == errSecSuccess && ref != NULL) ? (NSDictionary *)ref : nil; '
            'NSData *raw = item ? (NSData *)[item objectForKey:(id)kSecValueData] : nil; '
            'NSString *value = raw ? [[NSString alloc] initWithData:raw encoding:NSUTF8StringEncoding] : nil; '
            'id root = value ? [NSJSONSerialization JSONObjectWithData:[value dataUsingEncoding:NSUTF8StringEncoding] options:0 error:nil] : nil; '
            'NSString *name = nil; NSString *email = nil; NSInteger matches = 0; '
            'if ([(NSObject *)root isKindOfClass:[NSArray class]]) { for (NSDictionary *entry in (NSArray *)root) { '
            'NSDictionary *mail = (NSDictionary *)[entry objectForKey:@"mailAccount"]; '
            'NSString *candidate = (NSString *)[mail objectForKey:@"email"]; '
            f'if ([candidate isEqualToString:@"{escaped_email}"]) {{ matches += 1; email = candidate; name = (NSString *)[mail objectForKey:@"name"]; }} }} }} '
            'NSDate *modified = item ? (NSDate *)[item objectForKey:(id)kSecAttrModificationDate] : nil; '
            'NSISO8601DateFormatter *formatter = [[NSISO8601DateFormatter alloc] init]; '
            'formatter.formatOptions = NSISO8601DateFormatWithInternetDateTime | NSISO8601DateFormatWithFractionalSeconds; '
            'NSString *modifiedText = modified ? [formatter stringFromDate:modified] : @""; '
            'NSDictionary *safe = @{ @"marker":@"MailyAccountEvidenceV1", @"query_status":@(st), '
            '@"matching_account_count":@(matches), @"account_email":email ? (id)email : (id)[NSNull null], '
            '@"account_name":name ? (id)name : (id)[NSNull null], @"modified_at":modifiedText }; '
            'NSData *safeData = [NSJSONSerialization dataWithJSONObject:safe options:0 error:nil]; '
            'NSString *safeText = [[NSString alloc] initWithData:safeData encoding:NSUTF8StringEncoding]; '
            'if (ref) CFRelease(ref); safeText; })'
        )

    @staticmethod
    def _run_lldb_read(
        *,
        app_pid: int,
        expression: str,
        timeout_seconds: float,
    ) -> tuple[str, bool]:
        command_path: Path | None = None
        try:
            with tempfile.NamedTemporaryFile(
                mode="w",
                encoding="utf-8",
                prefix="maily-keychain-read-",
                suffix=".lldb",
                delete=False,
            ) as handle:
                handle.write("expr -l objc++ -- @import Foundation\n")
                handle.write("expr -l objc++ -- @import Security\n")
                handle.write(f"expr -l objc++ -O -- {expression}\n")
                handle.write("process detach\n")
                handle.write("quit\n")
                command_path = Path(handle.name)
            completed = subprocess.run(
                [
                    "lldb",
                    "--batch",
                    "--attach-pid",
                    str(app_pid),
                    "--source",
                    str(command_path),
                ],
                capture_output=True,
                text=True,
                timeout=timeout_seconds,
            )
            text = f"{completed.stdout}\n{completed.stderr}"
            detached = bool(re.search(r"Process\s+\d+\s+detached", text))
            if completed.returncode != 0:
                raise RuntimeError(
                    f"LLDB read-only query failed with exit code {completed.returncode}"
                )
            if not detached:
                raise RuntimeError("LLDB account query did not confirm process detach")
            return text, detached
        except subprocess.TimeoutExpired as exc:
            raise RuntimeError("LLDB read-only account query timed out") from exc
        finally:
            if command_path is not None:
                command_path.unlink(missing_ok=True)
            try:
                os.kill(app_pid, signal.SIGCONT)
            except ProcessLookupError:
                pass

    @staticmethod
    def _fetch_mailbox_messages(
        *,
        api_base_url: str,
        recipient_email: str,
        mailbox: str = "INBOX",
    ) -> list[dict[str, Any]]:
        encoded_user = quote(recipient_email, safe="")
        encoded_mailbox = quote(mailbox, safe="")
        request = Request(
            f"{api_base_url}/api/user/{encoded_user}/messages/{encoded_mailbox}",
            method="GET",
        )
        if request.get_method() != "GET":
            raise RuntimeError("strict read-only evaluator attempted a non-GET request")
        try:
            with urlopen(request, timeout=5.0) as response:
                payload = response.read()
        except (HTTPError, URLError) as exc:
            raise RuntimeError(f"GET mailbox failed for {recipient_email}: {exc}") from exc
        data = json.loads(payload.decode("utf-8"))
        if not isinstance(data, list):
            raise RuntimeError(f"mailbox payload must be a list, got {type(data)!r}")
        return [message for message in data if isinstance(message, dict)]
